g = 9.81;
x_end = 5;


simulation = {
  const n = 100;
  let totalTime = 0;
  const points = [];


  const baseForm = x =&gt; -Math.pow(x, 1.2); 

  const eta = x =&gt; Math.sin((Math.PI * x) / x_end);

  for (let i = 0; i &lt;= n; i++) {
    const x = (i / n) * x_end;

    const y = baseForm(x) + perturbation * eta(x);
    points.push({ x: x, y: y });
  }



  for (let i = 0; i &lt; n; i++) {
    const x1 = points[i].x;
    const y1 = points[i].y;
    const x2 = points[i+1].x;
    const y2 = points[i+1].y;

    const dx = x2 - x1;
    const dy = y2 - y1;
    const ds = Math.sqrt(dx * dx + dy * dy);


    const v1 = Math.sqrt(Math.max(0, -2 * g * y1));
    const v2 = Math.sqrt(Math.max(0, -2 * g * y2));

    const vAvg = (v1 + v2) / 2;

    if (vAvg &gt; 0.0001) {
      totalTime += ds / vAvg;
    } else {

      totalTime = Infinity;
      break; 
    }
  }

  return { points: points, time: totalTime };
}


